import java.util.Map;
import java.util.Optional;

/** Minimal in-memory HostStore; commit and replay facts share one synchronized boundary. */
public final class MemoryHostStore implements HostStore {
    private final Map<String, State> sessions = new LinkedHashMap<>();

    @Override
    public synchronized Commit commit(String sessionId, String commandId, String payloadHash, String resultRef,
                                      String eventType, byte[] eventPayload, long expectedSessionRevision) {
        State state = sessions.computeIfAbsent(sessionId, ignored -> new State());
        Journal prior = state.commands.get(commandId);
        if (prior != null) {
            if (!prior.payloadHash.equals(payloadHash)) throw new IllegalStateException("command.payload_conflict");
            return prior.commit;
        }
        if (state.snapshotRevision != expectedSessionRevision) throw new IllegalStateException("queue.revision_conflict");
        long accepted = ++state.acceptedSeq;
        long event = ++state.eventSeq;
        long revision = ++state.snapshotRevision;
        var durable = new DurableEvent(event, revision, eventType, eventPayload);
        state.events.add(durable);
        state.snapshotPayload = eventPayload.clone();
        state.snapshotBaseEventSeq = event;
        var commit = new Commit(accepted, event, revision, resultRef);
        state.commands.put(commandId, new Journal(payloadHash, commit));
        return commit;
    }

    @Override
    public synchronized Optional<Commit> command(String sessionId, String commandId, String payloadHash) {
        State state = sessions.get(sessionId);
        if (state == null || !state.commands.containsKey(commandId)) return Optional.empty();
        Journal journal = state.commands.get(commandId);
        if (!journal.payloadHash.equals(payloadHash)) throw new IllegalStateException("command.payload_conflict");
        return Optional.of(journal.commit);
    }

